import{_ as a,c as e,o as i,V as s}from"./chunks/framework.96b5c143.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/Earlier/Android后端-搭建一台属于自己的Linux服务器.md","lastUpdated":1681981355000}'),t={name:"blogs/Earlier/Android后端-搭建一台属于自己的Linux服务器.md"},o=s(`<blockquote><p>作为一个Android开发人员，总是与UI打交道，完全没有数据操作权限，有时候会感觉很苦恼，当自己突发奇想，想写个Demo练练手，却没有后端的支持，最终无疾而终。 所以接下来，我们先搭建一台自己的服务器吧，搭建自己的服务器有很多种方式：</p></blockquote><ul><li>用ApacheMonitor搭建一个服务端。</li><li>用WindosServer服务器或虚拟机用IIS搭建服务端。</li><li>用Linux搭建一台服务端。</li></ul><h3 id="如果你只需要用本地于测试-或者不考虑迁机的话-用上面第一种方式搭建个本地服务端就已经足够。" tabindex="-1">如果你只需要用本地于测试，或者不考虑迁机的话，用上面第一种方式搭建个本地服务端就已经足够。 <a class="header-anchor" href="#如果你只需要用本地于测试-或者不考虑迁机的话-用上面第一种方式搭建个本地服务端就已经足够。" aria-label="Permalink to &quot;如果你只需要用本地于测试，或者不考虑迁机的话，用上面第一种方式搭建个本地服务端就已经足够。&quot;">​</a></h3><h3 id="第一种方式最简单方便-往往在开发中用得较多-生活中我们所见的大部分几乎都是后两种。" tabindex="-1">第一种方式最简单方便，往往在开发中用得较多，生活中我们所见的大部分几乎都是后两种。 <a class="header-anchor" href="#第一种方式最简单方便-往往在开发中用得较多-生活中我们所见的大部分几乎都是后两种。" aria-label="Permalink to &quot;第一种方式最简单方便，往往在开发中用得较多，生活中我们所见的大部分几乎都是后两种。&quot;">​</a></h3><h2 id="第一种方式apachemonitor-由于近期重装了系统-服务挂了-界面是这样的" tabindex="-1">第一种方式ApacheMonitor（由于近期重装了系统，服务挂了，界面是这样的） <a class="header-anchor" href="#第一种方式apachemonitor-由于近期重装了系统-服务挂了-界面是这样的" aria-label="Permalink to &quot;第一种方式ApacheMonitor（由于近期重装了系统，服务挂了，界面是这样的）&quot;">​</a></h2><p><img src="http://upload-images.jianshu.io/upload_images/5174117-0bc8045ec838cc54.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="ApacheMonitor"></p><h2 id="第二种方式windosserver" tabindex="-1">第二种方式WindosServer <a class="header-anchor" href="#第二种方式windosserver" aria-label="Permalink to &quot;第二种方式WindosServer&quot;">​</a></h2><p><img src="http://upload-images.jianshu.io/upload_images/5174117-66e2c76e65057d3c.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="WindosServer"></p><h2 id="第三种方式linux" tabindex="-1">第三种方式Linux <a class="header-anchor" href="#第三种方式linux" aria-label="Permalink to &quot;第三种方式Linux&quot;">​</a></h2><p><img src="http://upload-images.jianshu.io/upload_images/5174117-dea687d05b037c18.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="Linux"></p><h2 id="结果展示" tabindex="-1">结果展示 <a class="header-anchor" href="#结果展示" aria-label="Permalink to &quot;结果展示&quot;">​</a></h2><h2 id="" tabindex="-1"><img src="http://upload-images.jianshu.io/upload_images/5174117-74f41f046d919058.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="www.peakchao.com"> <a class="header-anchor" href="#" aria-label="Permalink to &quot;![www.peakchao.com](http://upload-images.jianshu.io/upload_images/5174117-74f41f046d919058.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240)&quot;">​</a></h2><blockquote><p>Linux旗下有很多分支，大概包括：Debian，Ubuntu，CentOs，RedHat等等，如果再分清楚一点的话，他们还可以分为:有界面，无界面。一般来讲，为了节约系统资源，我推荐无界面，这里我使用虚拟机安装Ubuntu64位的长期支持版本。</p></blockquote><h2 id="虚拟机安装ubuntu" tabindex="-1">虚拟机安装Ubuntu <a class="header-anchor" href="#虚拟机安装ubuntu" aria-label="Permalink to &quot;虚拟机安装Ubuntu&quot;">​</a></h2><p><img src="http://upload-images.jianshu.io/upload_images/5174117-1f4d13d2ed1f55b6.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"><img src="http://upload-images.jianshu.io/upload_images/5174117-7e7027e185f6a5c9.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"><img src="http://upload-images.jianshu.io/upload_images/5174117-07db41025752515b.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-aa5bb62c11df915a.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-4df9961fa95483ad.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-4d9e1b6399776242.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-d642369c40bb7174.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-23f2480e39abe5bd.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-54003561652d202e.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-856a8fb6baab1b19.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-02b1dbf97bcc48ad.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="虚拟机安装"></p><h3 id="走到这一步后-保存设置然后开启虚拟机-会自动加载ios系统镜像-选择语言后-一路next默认安装即可-由于安装过程截图太多导致文章篇幅过长-所以省略其中步骤。" tabindex="-1">走到这一步后，保存设置然后开启虚拟机，会自动加载IOS系统镜像，选择语言后，一路next默认安装即可，由于安装过程截图太多导致文章篇幅过长，所以省略其中步骤。 <a class="header-anchor" href="#走到这一步后-保存设置然后开启虚拟机-会自动加载ios系统镜像-选择语言后-一路next默认安装即可-由于安装过程截图太多导致文章篇幅过长-所以省略其中步骤。" aria-label="Permalink to &quot;走到这一步后，保存设置然后开启虚拟机，会自动加载IOS系统镜像，选择语言后，一路next默认安装即可，由于安装过程截图太多导致文章篇幅过长，所以省略其中步骤。&quot;">​</a></h3><h2 id="启动截图" tabindex="-1">启动截图 <a class="header-anchor" href="#启动截图" aria-label="Permalink to &quot;启动截图&quot;">​</a></h2><p><img src="http://upload-images.jianshu.io/upload_images/5174117-88ef52dbab3f1e52.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="启动"></p><h3 id="启动后-只需输入刚才你填写的用户名和密码登陆即可。" tabindex="-1">启动后，只需输入刚才你填写的用户名和密码登陆即可。 <a class="header-anchor" href="#启动后-只需输入刚才你填写的用户名和密码登陆即可。" aria-label="Permalink to &quot;启动后，只需输入刚才你填写的用户名和密码登陆即可。&quot;">​</a></h3><p><img src="http://upload-images.jianshu.io/upload_images/5174117-cd9a99c5491cb9c0.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="登录后界面"></p><h2 id="安装ssh" tabindex="-1">安装SSH <a class="header-anchor" href="#安装ssh" aria-label="Permalink to &quot;安装SSH&quot;">​</a></h2><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">//安装</span></span>
<span class="line"><span style="color:#FFCB6B;">apt-get</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">install</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">openssh-server</span></span>
<span class="line"><span style="color:#FFCB6B;">//启动</span></span>
<span class="line"><span style="color:#FFCB6B;">service</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">ssh</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">start</span></span>
<span class="line"><span style="color:#FFCB6B;">//查看IP配置</span></span>
<span class="line"><span style="color:#FFCB6B;">ifconfig</span></span></code></pre></div><p><img src="http://upload-images.jianshu.io/upload_images/5174117-5009b87a77355685.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="IP信息"></p><h2 id="用ssh工具链接服务器-我用的xshell" tabindex="-1">用ssh工具链接服务器(我用的Xshell) <a class="header-anchor" href="#用ssh工具链接服务器-我用的xshell" aria-label="Permalink to &quot;用ssh工具链接服务器(我用的Xshell)&quot;">​</a></h2><p><img src="http://upload-images.jianshu.io/upload_images/5174117-78d90f529e55d0ec.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="配置连接信息和账号和密码"></p><p><img src="http://upload-images.jianshu.io/upload_images/5174117-239feedfc91efbaa.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="连接成功"></p><h2 id="安装http服务" tabindex="-1">安装HTTP服务 <a class="header-anchor" href="#安装http服务" aria-label="Permalink to &quot;安装HTTP服务&quot;">​</a></h2><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">//安装Nginx</span></span>
<span class="line"><span style="color:#FFCB6B;">apt-get</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">install</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">nginx</span></span></code></pre></div><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p><img src="http://upload-images.jianshu.io/upload_images/5174117-bff5dd7c90c458aa.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="测试"></p><h3 id="以上-一个简易的服务器就搭建完成了。" tabindex="-1">以上，一个简易的服务器就搭建完成了。 <a class="header-anchor" href="#以上-一个简易的服务器就搭建完成了。" aria-label="Permalink to &quot;以上，一个简易的服务器就搭建完成了。&quot;">​</a></h3><blockquote><p>放入我们自己的网站</p></blockquote><ul><li>新建html后缀的网页文件，内容如下：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">&lt;html&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;head&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;title&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">我的个人网站</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;/title&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;/head&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;body&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;h1 style=&quot;text-align: center&quot;&gt;这是我主页的内容&lt;/h1&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;/body&gt;</span></span>
<span class="line"><span style="color:#A6ACCD;">&lt;/html&gt;</span></span></code></pre></div><p><img src="http://upload-images.jianshu.io/upload_images/5174117-f94ae7d2e8d93edf.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="传输文件到服务器"></p><ul><li>刷新网站：</li></ul><p><img src="http://upload-images.jianshu.io/upload_images/5174117-cb608a0b5015a72d.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="我的网站"></p><h3 id="以后只需将自己的网页放入目录-即可通过浏览器预览-当然-这只是本地的-一个万网网站是需要一个外网服务器的-但是其操作步骤和上面是一摸一样。" tabindex="-1">以后只需将自己的网页放入目录，即可通过浏览器预览，当然，这只是本地的，一个万网网站是需要一个外网服务器的，但是其操作步骤和上面是一摸一样。 <a class="header-anchor" href="#以后只需将自己的网页放入目录-即可通过浏览器预览-当然-这只是本地的-一个万网网站是需要一个外网服务器的-但是其操作步骤和上面是一摸一样。" aria-label="Permalink to &quot;以后只需将自己的网页放入目录，即可通过浏览器预览，当然，这只是本地的，一个万网网站是需要一个外网服务器的，但是其操作步骤和上面是一摸一样。&quot;">​</a></h3><h3 id="推荐一个免费接口网站-我业余时间写的-https-www-jianshu-com-p-e6f072839282" tabindex="-1">推荐一个免费接口网站（我业余时间写的）：<a href="https://www.jianshu.com/p/e6f072839282" target="_blank" rel="noreferrer">https://www.jianshu.com/p/e6f072839282</a> <a class="header-anchor" href="#推荐一个免费接口网站-我业余时间写的-https-www-jianshu-com-p-e6f072839282" aria-label="Permalink to &quot;推荐一个免费接口网站（我业余时间写的）：https://www.jianshu.com/p/e6f072839282&quot;">​</a></h3><h3 id="我的博客网站-http-blog-peakchao-com" tabindex="-1">我的博客网站：<a href="http://blog.peakchao.com/" target="_blank" rel="noreferrer">http://blog.peakchao.com/</a> <a class="header-anchor" href="#我的博客网站-http-blog-peakchao-com" aria-label="Permalink to &quot;我的博客网站：http://blog.peakchao.com/&quot;">​</a></h3><p><img src="http://upload-images.jianshu.io/upload_images/5174117-0fea84322c236f70.png?imageMogr2/auto-orient/strip%7CimageView2/2/w/1240" alt="我的博客"></p>`,49),l=[o];function n(p,r,h,g,c,u){return i(),e("div",null,l)}const b=a(t,[["render",n]]);export{m as __pageData,b as default};
